/**
 * Resolves the same durable, event-scoped QR URL generated by the QR Code
 * Seating Chart.  Invitation senders must not construct a direct /s/:slug
 * link: slugs can change after an invitation has been sent.
 */
const DEFAULT_PUBLIC_BASE_URL = 'https://weddingwaitress.com.au';

export const buildCanonicalGuestSeatingUrl = (baseUrl: string, code: string) =>
  `${baseUrl.replace(/\/$/, '')}/qr/${encodeURIComponent(code)}`;

/** A recipient token deliberately lives in the query string, never in a guest ID route. */
export const buildRecipientInvitationUrl = (baseUrl: string, eventSlug: string, token: string) =>
  `${baseUrl.replace(/\/$/, '')}/s/${encodeURIComponent(eventSlug)}?invite=${encodeURIComponent(token)}`;

export const publicInvitationBaseUrl = () =>
  Deno.env.get('PUBLIC_BASE_URL')?.trim().replace(/\/$/, '') || DEFAULT_PUBLIC_BASE_URL;

type QueryResult<T> = PromiseLike<{ data: T; error: unknown }>;

type AdminClient = {
  from: (table: 'dynamic_qr_codes' | 'guest_access_tokens') => any;
  rpc: (
    name: 'generate_dynamic_qr_code' | 'get_or_create_guest_invitation_token',
    args?: Record<string, unknown>,
  ) => QueryResult<string | null>;
};

/**
 * Mints a server-only 256-bit guest access token and returns a link that does
 * not disclose a guest or event identifier.
 */
export async function resolveRecipientInvitationUrl(
  admin: AdminClient,
  eventId: string,
  eventSlug: string,
  guestId: string,
  baseUrl = publicInvitationBaseUrl(),
): Promise<string> {
  const bytes = new Uint8Array(32);
  crypto.getRandomValues(bytes);
  const token = btoa(String.fromCharCode(...bytes))
    .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  // SMS and email are sent concurrently. The database function serialises the
  // composite recipient row so both channels receive the same still-valid
  // token instead of racing to overwrite one another.
  const { data: persistedToken, error } = await admin.rpc('get_or_create_guest_invitation_token', {
    _event_id: eventId,
    _guest_id: guestId,
    _candidate_token: token,
    _expires_at: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(),
  });
  if (error || !persistedToken || !/^[A-Za-z0-9_-]{43}$/.test(persistedToken)) {
    throw new Error('The recipient invitation link could not be created.');
  }
  return buildRecipientInvitationUrl(baseUrl, eventSlug, persistedToken);
}

/** Returns the canonical public QR URL, minting a code for legacy events. */
export async function resolveCanonicalGuestSeatingUrl(
  admin: AdminClient,
  eventId: string,
  userId: string,
  baseUrl = publicInvitationBaseUrl(),
): Promise<string> {
  const { data: existing, error: lookupError } = await admin
    .from('dynamic_qr_codes')
    .select('code')
    .eq('current_event_id', eventId)
    .eq('is_active', true)
    .limit(1)
    .maybeSingle();

  if (lookupError) throw new Error('The event QR link could not be loaded.');
  if (existing?.code) return buildCanonicalGuestSeatingUrl(baseUrl, existing.code);

  // Matches useEventDynamicQR's legacy-event fallback, so invitations and QR
  // downloads always point to the same public event resolver.
  const { data: code, error: codeError } = await admin.rpc('generate_dynamic_qr_code');
  if (codeError || !code) throw new Error('The event QR link could not be created.');

  const { error: insertError } = await admin.from('dynamic_qr_codes').insert({
    code,
    user_id: userId,
    current_event_id: eventId,
    destination_type: 'guest_lookup',
    label: 'Auto-generated',
    is_active: true,
  });
  if (insertError) throw new Error('The event QR link could not be saved.');

  return buildCanonicalGuestSeatingUrl(baseUrl, code);
}
